    "v8": "conn_ctx",
    "v9": "conn_state_ptr",
    "v10": "irq_lock_counter_ptr",
    "v12": "irq_lock_counter",
    "v13": "irq_lock_counter_next",
    "v14": "irq_lock_saved",
    "v15": "rf_timer_snapshot"
