    },
    {
      "offset": 12,
      "meaning": "hw_tx_desc control field assigned from tx_desc_default"
    },
    {
      "offset": 36,
      "meaning": "hw_tx_desc total length field"
    },
    {
      "offset": 72,
      "meaning": "hw_tx_desc optional field conditionally cleared"
    },
